  totalPosition: "top" | "bottom";
}

const OrderSummaryTableSection = ({
  alignment,
  cardDetails = false,
  filled = false,
  surface,
  totalPosition,
}: TableSectionProps) => {
  const boxed = surface === "boxed";
  const totalBackground = boxed ? "#f3f4f6" : undefined;
  const summaryBackground = boxed && filled ? "#f9fafb" : undefined;
  const total = (
    <SummaryRow
      alignment={alignment}
      amount="$35.98"
      backgroundColor={totalBackground}
      label="Total"
      padded={boxed}
      total
    />
  );

  const summaryRows: ReactNode = (
    <>
      <SummaryRow
        alignment={alignment}
        amount="$29.99"
        backgroundColor={summaryBackground}
        label="Subtotal"
        padded={boxed && filled && totalPosition === "bottom"}
      />
      <GapRow />
      <SummaryRow
        alignment={alignment}
        amount="$5.99"
        backgroundColor={summaryBackground}
        label="Tax"
        padded={false}
      />
      <GapRow />
      <SummaryRow
        alignment={alignment}
        amount="FREE"
        backgroundColor={summaryBackground}
        label="Shipping"
        padded={false}
      />
    </>
  );

  return (
    <MjmlSection backgroundColor="#fffffe" padding="44px 24px">
      <MjmlColumn padding="0" width="552px">
        <MjmlTable
          cellpadding="0"
          cellspacing="0"
          cssClass="order-summary-full-table"
          padding="0"
          role="presentation"
          tableLayout="fixed"
          width="100%"
        >
          <tbody>
            {totalPosition === "top" ? (
              <>
                {total}
                {boxed ? <GapRow /> : <DividerRow />}
              </>
            ) : null}
            {summaryRows}
            {totalPosition === "bottom" ? (
              <>
                {boxed ? <GapRow /> : <DividerRow />}
                {total}
              </>
            ) : null}
            {cardDetails ? (
              <>
                {boxed ? null : <DividerRow margin={16} />}
                <CardDetailsRow alignment={alignment} boxed={boxed} />
              </>
            ) : null}
          </tbody>
        </MjmlTable>
      </MjmlColumn>
    </MjmlSection>
  );
};

